"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["94202"],{5390(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_etapa.conflito_de_concorrencia","status":409,"titulo":"Tipo de etapa alterado concorrentemente"},"descricao":{"codigo":"uniplus.configuracao.tipo_etapa.conflito_de_concorrencia","requisitos":[],"oQueAconteceu":["Duas altera\xe7\xf5es do mesmo tipo de etapa chegaram ao mesmo tempo, ou a lista de conceitos admitidos foi substitu\xedda por outra atualiza\xe7\xe3o durante a grava\xe7\xe3o. S\xf3 uma delas p\xf4de ser aplicada, e esta foi recusada. Nada deste pedido foi gravado.","A recusa descreve uma corrida que j\xe1 passou, n\xe3o um estado que permanece: a resposta traz `retryable: true`, e repetir o pedido pode dar certo. Por ser retent\xe1vel, a recusa n\xe3o prende a chave de idempot\xeancia do pedido.","A recusa vem por \xfaltimo: com um identificador inexistente prevalece [tipo de etapa n\xe3o encontrado](/erros/uniplus.configuracao.tipo_etapa.nao_encontrado), e com campos ou conceitos inv\xe1lidos prevalece a recusa de valida\xe7\xe3o correspondente."],"comoResolver":["Repita o pedido de atualiza\xe7\xe3o. Se a recusa se repetir, consulte o tipo de etapa para ver o que a outra altera\xe7\xe3o gravou e refa\xe7a o pedido sobre o conte\xfado atual, porque a atualiza\xe7\xe3o substitui os conceitos admitidos por inteiro."],"ondeAparece":["Atualiza\xe7\xe3o de um tipo de etapa (PUT /api/configuracao/admin/tipos-etapa/`{id}`), depois de o tipo de etapa ser encontrado e de os campos e os conceitos admitidos serem aprovados"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo etapa"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);